-- +goose Up
-- Hanko v0.1 schema. Vocabulary: docs/GLOSSARIO.md (ADR-0016).
-- All ids are UUIDv7 generated by the application. All timestamps timestamptz (UTC).
-- Every domain table carries company_id (ADR-0010).

CREATE TABLE companies (
    id          uuid PRIMARY KEY,
    slug        text NOT NULL UNIQUE,
    name        text NOT NULL,
    task_prefix text NOT NULL DEFAULT 'HNK' CHECK (task_prefix ~ '^[A-Z][A-Z0-9]{0,9}$'),
    timezone    text NOT NULL DEFAULT 'America/Sao_Paulo',
    next_task_number bigint NOT NULL DEFAULT 1,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE workspaces (
    id          uuid PRIMARY KEY,
    company_id  uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    slug        text NOT NULL,
    name        text NOT NULL,
    path        text NOT NULL,
    repo_url    text NOT NULL DEFAULT '',
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (company_id, slug)
);

CREATE TABLE projects (
    id           uuid PRIMARY KEY,
    company_id   uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    slug         text NOT NULL,
    name         text NOT NULL,
    description  text NOT NULL DEFAULT '',
    workspace_id uuid REFERENCES workspaces(id) ON DELETE SET NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    UNIQUE (company_id, slug)
);

CREATE TABLE personas (
    id                      uuid PRIMARY KEY,
    company_id              uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    slug                    text NOT NULL,
    name                    text NOT NULL,
    title                   text NOT NULL DEFAULT '',
    instructions            text NOT NULL DEFAULT '',
    agent                   text NOT NULL CHECK (agent IN ('claude','codex','fake')),
    model                   text NOT NULL DEFAULT '',
    adapter_config          jsonb NOT NULL DEFAULT '{}'::jsonb,
    status                  text NOT NULL DEFAULT 'active'
                            CHECK (status IN ('active','idle','running','paused','error','awaiting_gate','off')),
    reports_to              uuid REFERENCES personas(id) ON DELETE SET NULL,
    workspace_id            uuid REFERENCES workspaces(id) ON DELETE SET NULL,
    heartbeat_interval_sec  integer NOT NULL DEFAULT 0 CHECK (heartbeat_interval_sec >= 0),
    budget_monthly_cents    bigint CHECK (budget_monthly_cents IS NULL OR budget_monthly_cents >= 0),
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    UNIQUE (company_id, slug)
);

CREATE TABLE tasks (
    id                uuid PRIMARY KEY,
    company_id        uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    number            bigint NOT NULL,
    title             text NOT NULL CHECK (length(title) BETWEEN 1 AND 500),
    description       text NOT NULL DEFAULT '',
    status            text NOT NULL DEFAULT 'todo'
                      CHECK (status IN ('backlog','todo','in_progress','in_review','blocked','done','cancelled')),
    priority          text NOT NULL DEFAULT 'medium' CHECK (priority IN ('critical','high','medium','low')),
    persona_id        uuid REFERENCES personas(id) ON DELETE SET NULL,
    project_id        uuid REFERENCES projects(id) ON DELETE SET NULL,
    workspace_id      uuid REFERENCES workspaces(id) ON DELETE SET NULL,
    parent_id         uuid REFERENCES tasks(id) ON DELETE SET NULL,
    created_by_type   text NOT NULL CHECK (created_by_type IN ('human','persona','system')),
    created_by_id     uuid,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    closed_at         timestamptz,
    UNIQUE (company_id, number)
);
CREATE INDEX tasks_company_status_idx ON tasks (company_id, status, updated_at DESC);
CREATE INDEX tasks_persona_idx ON tasks (persona_id) WHERE persona_id IS NOT NULL;

CREATE TABLE task_comments (
    id           uuid PRIMARY KEY,
    company_id   uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    task_id      uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    author_type  text NOT NULL CHECK (author_type IN ('human','persona','system')),
    author_id    uuid,
    run_id       uuid,
    body         text NOT NULL CHECK (length(body) BETWEEN 1 AND 100000),
    event_id     text,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX task_comments_task_idx ON task_comments (task_id, created_at);
CREATE UNIQUE INDEX task_comments_event_uq ON task_comments (company_id, event_id) WHERE event_id IS NOT NULL;

CREATE TABLE runs (
    id                     uuid PRIMARY KEY,
    company_id             uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    task_id                uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    persona_id             uuid NOT NULL REFERENCES personas(id) ON DELETE CASCADE,
    status                 text NOT NULL DEFAULT 'queued'
                           CHECK (status IN ('queued','running','done','interrupted','failed','cancelled','expired')),
    trigger                text NOT NULL CHECK (trigger IN ('assign','comment','manual','heartbeat')),
    agent                  text NOT NULL,
    model                  text NOT NULL DEFAULT '',
    session_ref            text NOT NULL DEFAULT '',
    trace_id               text NOT NULL DEFAULT '',
    exit_code              integer,
    error                  text NOT NULL DEFAULT '',
    summary                text NOT NULL DEFAULT '',
    cost_usd               numeric(14,6),
    input_tokens           bigint NOT NULL DEFAULT 0,
    output_tokens          bigint NOT NULL DEFAULT 0,
    cache_read_tokens      bigint NOT NULL DEFAULT 0,
    cache_creation_tokens  bigint NOT NULL DEFAULT 0,
    handoff_in             text NOT NULL DEFAULT '',
    handoff_out            text NOT NULL DEFAULT '',
    created_at             timestamptz NOT NULL DEFAULT now(),
    started_at             timestamptz,
    finished_at            timestamptz
);
-- Atomic checkout: at most one active run per task.
CREATE UNIQUE INDEX runs_one_active_per_task ON runs (task_id) WHERE status IN ('queued','running');
CREATE INDEX runs_company_created_idx ON runs (company_id, created_at DESC);
CREATE INDEX runs_persona_idx ON runs (persona_id, created_at DESC);

CREATE TABLE run_events (
    id           uuid PRIMARY KEY,
    company_id   uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    run_id       uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
    seq          bigint NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('system','assistant','thinking','tool_use','tool_result','stdout','stderr','result','status')),
    text         text NOT NULL DEFAULT '',
    payload      jsonb,
    occurred_at  timestamptz NOT NULL,
    received_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (run_id, seq)
);

CREATE TABLE activity_events (
    id            uuid PRIMARY KEY,
    company_id    uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    actor_type    text NOT NULL CHECK (actor_type IN ('human','persona','system')),
    actor_id      uuid,
    verb          text NOT NULL,
    subject_type  text NOT NULL,
    subject_id    uuid NOT NULL,
    data          jsonb NOT NULL DEFAULT '{}'::jsonb,
    event_id      text,
    occurred_at   timestamptz NOT NULL,
    received_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX activity_company_occurred_idx ON activity_events (company_id, occurred_at DESC);
CREATE INDEX activity_subject_idx ON activity_events (subject_type, subject_id, occurred_at DESC);
CREATE UNIQUE INDEX activity_event_uq ON activity_events (company_id, event_id) WHERE event_id IS NOT NULL;

-- Memory outbox (ADR-0015): facts to deliver to the memory provider, written in the
-- same transaction as the domain change, delivered by a river job with retry.
CREATE TABLE memory_outbox (
    id            uuid PRIMARY KEY,
    company_id    uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    workspace_id  uuid REFERENCES workspaces(id) ON DELETE SET NULL,
    kind          text NOT NULL,
    payload       jsonb NOT NULL,
    event_id      text NOT NULL,
    status        text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','failed')),
    attempts      integer NOT NULL DEFAULT 0,
    last_error    text NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL DEFAULT now(),
    sent_at       timestamptz,
    UNIQUE (company_id, event_id)
);
CREATE INDEX memory_outbox_pending_idx ON memory_outbox (created_at) WHERE status = 'pending';

-- +goose Down
DROP TABLE memory_outbox;
DROP TABLE activity_events;
DROP TABLE run_events;
DROP TABLE runs;
DROP TABLE task_comments;
DROP TABLE tasks;
DROP TABLE personas;
DROP TABLE projects;
DROP TABLE workspaces;
DROP TABLE companies;
